command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="e70d3ec5c91118acd113f2d90cb6a37f1c7c4ac8";$candidate="e4c95e1c2e7c1a3ca1f3530dac86f4477c1664a3";$branch="work/unc-network-shell-visuals-20261007"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "network visual FAST3 fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before network visual FAST3"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "network visual FAST3 candidate moved"}
$temp=Join-Path $env:RUNNER_TEMP ("fly-network-visual-fast3-"+$env:GITHUB_RUN_ID)
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
try{
 & git worktree add --detach $temp $candidate
 if($LASTEXITCODE -ne 0){throw "network visual FAST3 worktree add failed"}
 Set-Location -LiteralPath $temp
 & git diff --check ($main+"..."+$candidate)
 if($LASTEXITCODE -ne 0){throw "network visual FAST3 diff check failed"}
 & python -X utf8 tools\winui\run_checks.py fast --before $main --head $candidate
 if($LASTEXITCODE -ne 0){throw "network visual FAST3 failed"}
 Write-Host "NETWORK_VISUAL_FAST3_DIFF_CHECK=PASS"
 Write-Host "NETWORK_VISUAL_FAST3=PASS"
 Write-Host "NETWORK_VISUAL_REUSED_BEFORE_RUN=37575384608"
}finally{
 Set-Location -LiteralPath $repo
 if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
 & git worktree prune
}
